(5389183, 773355, 100495, '<td valign="top">I like the colours and the perspective, but the walker doesn''t really add anything for me.</td>', 'I like the colours and the perspective, but the walker doesn''t really add anything for me.', '2009-03-18 09:42:47.000000', NULL, 1),
(5389191, 773391, 100495, '<td valign="top">Nice bokeh.  Should have been 640 px wide for maximum effect.</td>', 'Nice bokeh.  Should have been 640 px wide for maximum effect.', '2009-03-18 09:44:24.000000', NULL, 1),
(5389319, 774150, 100205, '<td valign="top">This photograph is wonderful for showing what the eye often misses. I wouldn''t normally imagine the blue smoke (or fumes/very hot flame??) on the flame of a match, but here it is and the colours complement each other well. Composition wise, I''m not sure if this was framed/cropped afterwards too closely - the bottom blue curve looks cropped off (even if it isn''t there, I would like to imagine that curl sweeping from the left, down and around up the right side).</td>', 'This photograph is wonderful for showing what the eye often misses. I wouldn''t normally imagine the blue smoke (or fumes/very hot flame??) on the flame of a match, but here it is and the colours complement each other well. Composition wise, I''m not sure if this was framed/cropped afterwards too closely - the bottom blue curve looks cropped off (even if it isn''t there, I would like to imagine that curl sweeping from the left, down and around up the right side).', '2009-03-18 10:37:41.000000', NULL, 1),
(5389372, 773291, 56400, '<td valign="top">I would be curious to know what the streak in the mid upper right side of the shot was. Airplane contrail or satellite pass? Nice shot.</td>', 'I would be curious to know what the streak in the mid upper right side of the shot was. Airplane contrail or satellite pass? Nice shot.', '2009-03-18 11:06:26.000000', NULL, 1),
(5389381, 774166, 56400, '<td valign="top">I''m not sure the ring could be considered a "light source" per the rules, but a nice shot otherwise.</td>', 'I''m not sure the ring could be considered a "light source" per the rules, but a nice shot otherwise.', '2009-03-18 11:11:41.000000', NULL, 1),
(5389382, 773833, 17011, '<td valign="top">Very interesting photo with the entire subject being the challenge.. well done</td>', 'Very interesting photo with the entire subject being the challenge.. well done', '2009-03-18 11:11:46.000000', NULL, 1),
