(5391523, 773319, 100495, '<td valign="top">It''s a well-controlled photo of a rather dull subject. I feel it could be improved quite easily with a different composition (off-centred for example) or a tilt, or an abstract close-up or a lot of dead space to one side.</td>', 'It''s a well-controlled photo of a rather dull subject. I feel it could be improved quite easily with a different composition (off-centred for example) or a tilt, or an abstract close-up or a lot of dead space to one side.', '2009-03-19 11:05:58.000000', NULL, 1),
(5391526, 773182, 100495, '<td valign="top">I like the way you''ve exposed the light against the bright sky, I like the blurred background and the red flowers.  However, it doesn''t feel very well composed and more of a snap shot than a challenge entry.</td>', 'I like the way you''ve exposed the light against the bright sky, I like the blurred background and the red flowers.  However, it doesn''t feel very well composed and more of a snap shot than a challenge entry.', '2009-03-19 11:08:22.000000', NULL, 1),
(5391527, 773977, 100495, '<td valign="top">Nice. Your lighting has a smokey effect which is quite different from the usual crisp light painting. ETA: it almost looks solid, like cotton wool.</td>', 'Nice. Your lighting has a smokey effect which is quite different from the usual crisp light painting. ETA: it almost looks solid, like cotton wool.', '2009-03-19 11:09:46.000000', NULL, 1),
(5391534, 773549, 100495, '<td valign="top">Right then, this just looks like a collection of clip art, in which case it would be DQ''d.<br/> <br/>However, if the face effect was legally created that really would be something impressive. I''m looking forward to see what this actually is and how it was done.</td>', 'Right then, this just looks like a collection of clip art, in which case it would be DQ''d. However, if the face effect was legally created that really would be something impressive. I''m looking forward to see what this actually is and how it was done.', '2009-03-19 11:13:07.000000', NULL, 1),
(5391538, 773564, 100495, '<td valign="top">Great colours and a feeling of movement.<br/> <br/>Obviously it''s OOF, but I don''t know if it''s possible to focus on one of these things so I''m assuming it''s not, otherwise you''d have nailed the focus, right?<br/> <br/>Good exposure.</td>', 'Great colours and a feeling of movement. Obviously it''s OOF, but I don''t know if it''s possible to focus on one of these things so I''m assuming it''s not, otherwise you''d have nailed the focus, right? Good exposure.', '2009-03-19 11:14:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5391542, 773061, 100495, '<td valign="top">This looks like fireworks in the garden.  The colours look quite subdued and the sparks look like they''re not properly in focus (I think the focus was on the glowing embers in the foreground).</td>', 'This looks like fireworks in the garden.  The colours look quite subdued and the sparks look like they''re not properly in focus (I think the focus was on the glowing embers in the foreground).', '2009-03-19 11:16:28.000000', NULL, 1),
(5391545, 774196, 100495, '<td valign="top">That''s a really interesting building, but the logo is quite distractive. You could have used something to hide the logo, maybe an alien figure or something.  Good deep colours.</td>', 'That''s a really interesting building, but the logo is quite distractive. You could have used something to hide the logo, maybe an alien figure or something.  Good deep colours.', '2009-03-19 11:17:55.000000', NULL, 1),
(5391547, 773517, 100495, '<td valign="top">Don''t know what it is but I like it. It feels like it needs a bit more space on the right though.  Good colours.</td>', 'Don''t know what it is but I like it. It feels like it needs a bit more space on the right though.  Good colours.', '2009-03-19 11:18:53.000000', NULL, 1),
(5391552, 774376, 100495, '<td valign="top">I like the heat in the top right hand corner. The ambient light is a little bright to bring out the deep reds in the log and a later shot might have helped that, but also might have ruined it too.</td>', 'I like the heat in the top right hand corner. The ambient light is a little bright to bring out the deep reds in the log and a later shot might have helped that, but also might have ruined it too.', '2009-03-19 11:20:28.000000', NULL, 1),
(5391562, 774248, 100495, '<td valign="top">I think this is neither a presentation of an object nor an abstract.  The colours and processing are great, the black is a really black and the central focus draws my attention. But it feels like it could have been a lot better if it were just a little different.</td>', 'I think this is neither a presentation of an object nor an abstract.  The colours and processing are great, the black is a really black and the central focus draws my attention. But it feels like it could have been a lot better if it were just a little different.', '2009-03-19 11:27:38.000000', NULL, 1),
(5391564, 774113, 100495, '<td valign="top">Nice composition and lighting. I''m a little distracted by the writing down the right hand side though.</td>', 'Nice composition and lighting. I''m a little distracted by the writing down the right hand side though.', '2009-03-19 11:28:46.000000', NULL, 1),
(5391567, 774269, 100495, '<td valign="top">Really good detail and colours.<br/> <br/>A longer exposure or more than 1 sparkler might have added more ''shooting'' stars though.</td>', 'Really good detail and colours. A longer exposure or more than 1 sparkler might have added more ''shooting'' stars though.', '2009-03-19 11:29:53.000000', NULL, 1),
(5391584, 774337, 100495, '<td valign="top">From the thumbnail it looked like somebody suffering from S.A.D.<br/> <br/>Great detail and lighting, but the crop looks a little awkward at the top.</td>', 'From the thumbnail it looked like somebody suffering from S.A.D. Great detail and lighting, but the crop looks a little awkward at the top.', '2009-03-19 11:36:49.000000', NULL, 1),
(5391591, 773854, 100495, '<td valign="top">Excellent blue and great bokeh and good DOF.<br/> <br/>The centred composition is a little plain though and needs something else to add interest, like a tilt or a diagonal or something.</td>', 'Excellent blue and great bokeh and good DOF. The centred composition is a little plain though and needs something else to add interest, like a tilt or a diagonal or something.', '2009-03-19 11:42:49.000000', NULL, 1),
