(5396890, 774236, 35602, '<td valign="top">Love this.  Great shot for all of us folks who have to still deal with below freezing temps at night.  Wish I were there.</td>', 'Love this.  Great shot for all of us folks who have to still deal with below freezing temps at night.  Wish I were there.', '2009-03-23 16:17:53.000000', NULL, 1),
